import { Request, Response } from "express";
import puppeteer from "puppeteer-core";

// ── Types ─────────────────────────────────────────────────────────────────────
interface Unit {
  id?: string;
  unitNumber?: string;
  floor?: string;
  area?: string | number;
  unitType?: string;
  type?: string;
  description?: string;
  features?: string;
  pricePerMeter?: string;
  monthlyRent?: string | number;
  contractDuration?: string;
  status?: string;
}

interface ProjectData {
  projectName: string;
  projectType: string;
  city: string;
  district: string;
  totalArea?: string | number;
  leasableArea?: string | number;
  floors?: string | number;
  completionYear?: string;
  description?: string;
  amenities?: string;
  contactName?: string;
  features?: string | string[];
  contactPhone?: string;
  contactEmail?: string;
  projectImage?: string;
  units?: string | number | Unit[];
  units_list?: Unit[];
  annualRent?: string | number;
  occupancyRate?: string | number;
}

// ── Constants ─────────────────────────────────────────────────────────────────
// Delmon official brand colors (from 2026 profile)
const GOLD = "#C9A84C";          // شعار دلمون الذهبي — للشعار فقط
const DELMON_BLUE = "#4A6FB5";   // الأزرق الرسمي لدلمون — للعناصر والـ accents
const DELMON_LIGHT_BLUE = "#5B7EC9"; // أزرق فاتح للأيقونات والتفاصيل
const DARK_BG = "#0F1117";       // للقالب Dark Luxury فقط
const DARK_PANEL = "#1A1F2E";    // للقالب Dark Luxury فقط
const DELMON_WHITE = "#FFFFFF";  // الخلفية الرئيسية
const DELMON_LIGHT_GRAY = "#F7F8FA"; // خلفية ثانوية فاتحة
const DELMON_BORDER = "#E2E8F0"; // حدود رفيعة
const DELMON_TEXT = "#1A2B4A";   // نص داكن رسمي
const DELMON_TEXT_LIGHT = "#64748B"; // نص ثانوي
const LOGO_REF = "data:image/svg+xml;base64,";
const COLL1 = "data:image/jpeg;base64,";
const HOTEL_IMG = "data:image/jpeg;base64,";
const RAVALA_IMG = "data:image/jpeg;base64,";
const MAARID_IMG = "data:image/jpeg;base64,";
const COLL2 = "data:image/jpeg;base64,";
const COLL3 = "data:image/jpeg;base64,";
const COLL4 = "data:image/jpeg;base64,";

const LOGO = "data:image/png;base64,";

// ── Helpers ───────────────────────────────────────────────────────────────────
function kpiBar(kpis: {v:string,l:string}[], bg: string, numColor: string, lblColor: string, border: string) {
  return kpis.map(k => `
    <div style="flex:1;background:${bg};border-radius:6px;padding:10px 6px;text-align:center;border-top:3px solid ${border}">
      <div style="font-size:20px;font-weight:900;color:${numColor};line-height:1">${k.v}</div>
      <div style="font-size:8px;color:${lblColor};margin-top:3px;font-weight:600">${k.l}</div>
    </div>`).join("");
}

function amenityTags(list: string[], bg: string, color: string, border: string) {
  return list.map(a => `<span style="background:${bg};border:1px solid ${border};color:${color};font-size:8.5px;padding:3px 9px;border-radius:20px;font-weight:600">${a}</span>`).join("");
}

function footer(page: string, bg: string, textColor: string, accentColor: string) {
  return `
  <div style="height:5mm;background:${bg};display:flex;align-items:center;justify-content:space-between;padding:0 22px;flex-shrink:0;border-top:1px solid rgba(74,111,181,0.25)">
    <span style="color:${textColor};font-size:7.5px;font-weight:600;opacity:0.55">${page}</span>
    <div style="display:flex;align-items:center;gap:6px">
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 68" width="10" height="14"><path d="M24,4 C24,4 6,22 6,38 C6,50 14,60 24,60 C34,60 42,50 42,38 C42,22 24,4 24,4 Z" fill="none" stroke="${accentColor}" stroke-width="3"/><circle cx="24" cy="40" r="5" fill="${accentColor}"/></svg>
      <span style="color:${textColor};font-size:7.5px;font-weight:700;opacity:0.7">أعمال دلمون للعقارات</span>
    </div>
    <span style="color:${textColor};font-size:7px;opacity:0.5">delmoninvest.com</span>
  </div>`;
}

